fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn dims() -> i32 { (320 << 16) | 480 }

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, (h / 2) * 8);
        host::display::state_set(2, 0);
        host::display::state_set(3, w + 40);
        host::display::state_set(4, 90 + hash(1) % (h - 180));
        host::display::state_set(5, 0);
        host::display::state_set(6, 0);
        host::display::state_set(8, 1);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(7) == 0;
    host::display::state_set(7, down);
    if host::display::state_get(6) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(90, 160, "SPLAT", 0xff4040, 4);
        host::display::draw_string(60, 230, "PIPES", 0x808080, 2);
        host::display::draw_number(160, 224, host::display::state_get(5), 0xffffff, 3);
        host::display::draw_string(60, 264, "BEST", 0x808080, 2);
        host::display::draw_number(160, 258, host::display::state_get(9), 0x00ff88, 3);
        host::display::draw_string(70, 330, "TAP TO FLAP", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut yf: i32 = host::display::state_get(1);
        let mut vy: i32 = host::display::state_get(2);
        if tap { vy = -38; }
        vy = vy + 3;
        if vy > 44 { vy = 44; }
        yf = yf + vy;
        host::display::state_set(1, yf);
        host::display::state_set(2, vy);
        let py: i32 = yf / 8;
        let mut pxp: i32 = host::display::state_get(3) - 3;
        let mut gy: i32 = host::display::state_get(4);
        let mut score: i32 = host::display::state_get(5);
        if pxp < -48 {
            pxp = w;
            let rnd: i32 = host::display::state_get(8) + 1;
            host::display::state_set(8, rnd);
            gy = 90 + hash(rnd) % (h - 180);
            score = score + 1;
            host::display::state_set(5, score);
        }
        host::display::state_set(3, pxp);
        host::display::state_set(4, gy);
        let mut dead: i32 = 0;
        if py < 0 || py + 22 > h { dead = 1; }
        if 60 + 22 > pxp && 60 < pxp + 48 {
            if py < gy - 70 || py + 22 > gy + 70 { dead = 1; }
        }
        if dead == 1 {
            host::display::state_set(6, 1);
            if score > host::display::state_get(9) {
                host::display::state_set(9, score);
            }
        }
        host::display::clear(0x102030);
        host::display::fill_rect(pxp, 0, 48, gy - 70, 0x22aa44);
        host::display::fill_rect(pxp, gy + 70, 48, h - gy - 70, 0x22aa44);
        host::display::fill_rect(pxp - 4, gy - 86, 56, 16, 0x2fcc55);
        host::display::fill_rect(pxp - 4, gy + 70, 56, 16, 0x2fcc55);
        host::display::fill_rect(60, py, 22, 22, 0xffdd00);
        host::display::fill_rect(76, py + 6, 8, 6, 0xff8800);
        host::display::draw_number(w / 2 - 12, 16, score, 0xffffff, 4);
    }
    host::display::present();
}
